def event(self, payload: dict, at: float) -> None:
    self.events.append(payload)
    kind, data = payload.get("type"), payload.get("data", {})
    if kind == "session_started":
        self.ready = True

@room.on("data_received")
def on_data(packet):
    at = time.monotonic()
    participant = packet.participant
    record("data_packet", participant=participant.identity if participant else None, topic=packet.topic,
           payload_base64=base64.b64encode(packet.data).decode())
    if packet.topic == "agent-events" and participant and participant.kind == rtc.ParticipantKind.PARTICIPANT_KIND_AGENT:
        try:
            payload = json.loads(packet.data)
            record("coordinator_event", event=payload, observed_monotonic=at)
            state.event(payload, at)
        except (ValueError, KeyError, TypeError) as error:
            errors.append(f"coordinator event could not be interpreted: {error!r}")
            record("data_error", error=repr(error))
        changed.set()

def _retrieve_remote_participant(self, identity: str) -> Optional[RemoteParticipant]:
    """Retrieve a remote participant by identity"""
    return self._remote_participants.get(identity, None)

def _on_room_event(self, event: proto_room.RoomEvent) -> None:
    which = event.WhichOneof("message")
    if which == "participant_connected":
        rparticipant = self._create_remote_participant(event.participant_connected.info)
        self.emit("participant_connected", rparticipant)
